import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { format } from "prettier";
import {
  spacingPrimitives,
  spacingDensity,
  semanticSpacing,
} from "../packages/tokens/src/spacing.ts";
import { componentSpacing } from "../packages/react/src/tokens/component-spacing.ts";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const header =
  "/* Generated by scripts/generate-spacing.mjs. Do not edit. */\n";
const block = (selector, values) =>
  `  ${selector} {\n${values.map(([name, value]) => `    --dixy-${name}: ${value};`).join("\n")}\n  }\n`;
const primitives = Object.entries(spacingPrimitives)
  .sort((a, b) => a[1] - b[1])
  .map(([id, px]) => [`space-${id}`, px === 0 ? "0" : `${px / 16}rem`]);
// Place :root defaults before modes so density also works on the html element.
const densityEntries = [
  ["default", spacingDensity.default],
  ...Object.entries(spacingDensity).filter(
    ([density]) => density !== "default",
  ),
];
const semantics = densityEntries.map(([density, groups]) =>
  block(
    density === "default"
      ? ':root,\n  [data-dixy-density="default"]'
      : `[data-dixy-density="${density}"]`,
    Object.entries(groups).flatMap(([family, sizes]) =>
      Object.entries(sizes).map(([size, token]) => [
        `spacing-${family}-${size}`,
        `var(--dixy-space-${token})`,
      ]),
    ),
  ),
);

const css = `${header}@layer dixy.tokens {\n${block(":root", primitives)}${semantics.join("")}\n}\n`;
// Rebind aliases at each density boundary: CSS var() aliases resolve where declared.
const componentCss = `${header}@layer dixy.tokens {\n${block(
  ":root,\n  [data-dixy-density]",
  Object.entries(componentSpacing).map(([name, [family, size]]) => [
    name,
    `var(--dixy-spacing-${family}-${size})`,
  ]),
)}}\n`;
const outputs = {
  "packages/tokens/src/spacing.css": css,
  "packages/react/src/tokens/component-spacing.css": componentCss,
  "packages/react/src/tokens/layout-spacing.css": `${header}@layer dixy.components {\n${["stack", "inline"].flatMap((family) => Object.keys(semanticSpacing[family]).map((size) => `  .dixy-${family}[data-gap="${size}"] { gap: var(--dixy-spacing-${family}-${size}); }`)).join("\n")}\n}\n`,
};
if (process.argv.includes("--dist"))
  outputs["packages/tokens/dist/spacing.css"] = css;
for (const [file, rawContent] of Object.entries(outputs)) {
  const content = await format(rawContent, { parser: "css" });
  const target = path.join(root, file);
  const current = fs.existsSync(target) ? fs.readFileSync(target, "utf8") : "";
  if (process.argv.includes("--check")) {
    if (current !== content)
      throw new Error(`${file} is stale. Run pnpm tokens:generate.`);
  } else if (current !== content) {
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, content);
  }
}
console.log(
  process.argv.includes("--check")
    ? "Spacing outputs match their canonical contracts."
    : "Spacing CSS generated from token contracts.",
);
